@Configuration
public class TraspasosCuentaGlobalJobConfig {

    /** WKS-TSK-OPCION llega como parámetro del job: 0 aplica archivos, 1 solo plancha fechas. */
    @Bean
    JobExecutionDecider modoOperacion() {
        return (jobExec, stepExec) -> new FlowExecutionStatus(
                "1".equals(jobExec.getJobParameters().getString("opcion")) ? "SOLO_FECHA" : "NORMAL");
    }

    @Bean
    Job traspasosCuentaGlobal(JobRepository repo, Step inicio, Step armaCola,
                              Step aplicaArchivos, Step reportaArchivos,
                              Step soloFecha, Step historicoLigas, Step actualizaControl) {
        return new JobBuilder("S500P186", repo)
                .start(inicio)                       // 00001000 .. 20020000
                .next(modoOperacion())
                    .on("NORMAL").to(armaCola)       // 40901000-ARMA-ARCH-PEND
                        .next(aplicaArchivos)        // 50000000-APLICA-ARCHIVOS (particionado)
                        .next(reportaArchivos)
                        .next(historicoLigas)        // barrido de S500B05PHISCTAGLB
                        .next(actualizaControl)
                .from(modoOperacion())
                    .on("SOLO_FECHA").to(soloFecha)  // 40901500-SOLO-FECHA
                        .next(actualizaControl)      // decisión explícita: sin barrido de ligas
                .end()
                .build();
    }
}

