@Component
@RequiredArgsConstructor
public class DispersionS274 {

    private final P186Properties.S274 cfg;
    private final AtomicLong autorizacion = new AtomicLong();   // W77-MY-AUTORIZ

    public AbonoS274 abono(TraspasoRecord t, CuentaGlobal cta, String sistemaOrigen) {
        long referencia = cfg.sinReferencia().contains(sistemaOrigen) || t.fechaTraspaso() == null
                ? 0L : Fixed.aaaammdd(t.fechaTraspaso());
        return new AbonoS274(
                autorizacion.incrementAndGet(),
                t.importeMn(),                                   // 9(14)V99, sin conversión
                cfg.tipoCuenta(),
                cta.sucursalOrigen(), cta.nuevoContrato(),
                cfg.clavePorSistema().getOrDefault(sistemaOrigen, cfg.claveDefault()),
                referencia,
                LeyendaEstadoCuenta.de(cta));                    // WKS-LEY-S274-EDOCTA
    }
}

/** El trailer de E02 acumula número e importe de abonos (WKS-E02-R09-*). */

@Component
@StepScope
@RequiredArgsConstructor
public class ReactivacionProcessor implements ItemProcessor<RegistroTraspaso, Salida> {

    private final HistoricoCuentaGlobalRepository b05p;
    private final DispersionS274 dispersion;
    private final CifrasControl cifras;

    @Override
    @Transactional
    public Salida process(RegistroTraspaso reg) {
        var t = TraspasoRecord.parse(reg.raw());              // tipo 4, mismo layout que el 3
        var hist = b05p.findByOrigenForUpdate(t)               // B05PXORIG-LOCK
                .orElse(null);
        if (hist == null) return Salida.rechazo(reg, Rechazo.of(13));
        if (hist.estatusBenef() != 3 && hist.estatusBenef() != 5) {
            return Salida.rechazo(reg, Rechazo.of(17));        // solo se reactiva liga pendiente o cancelada
        }
        hist.reactiva();          // estatus 2, fecha e importe de beneficencia en cero
        cifras.suma(t, LlaveTotales.de(t.producto(), t.instrumento(), t.moneda(), 0));
        return Salida.de(
                RegistroS016.reactivacion(hist),
                dispersion.reactivacion(t, hist));             // E02-DISP-REAC-S274, clave 1300
    }
}

@Bean
ClassifierCompositeItemWriter<AbonoS274> escritorS274(
        FlatFileItemWriter<AbonoS274> dispS274,       // E02-DISP-S274
        FlatFileItemWriter<AbonoS274> dispReacS274) {  // E02-DISP-REAC-S274
    var w = new ClassifierCompositeItemWriter<AbonoS274>();
    w.setClassifier(a -> a.esReactivacion() ? dispReacS274 : dispS274);
    return w;
}

// En DispersionS274:
public AbonoS274 reactivacion(TraspasoRecord t, HistoricoCuentaGlobal h) {
    return new AbonoS274(
            autorizacion.incrementAndGet(),     // mismo consecutivo W77-MY-AUTORIZ que los traspasos
            t.importeMn(), cfg.tipoCuenta(),
            h.sucursalOrigen(), h.nuevoContrato(),
            cfg.claveReactivacion(),            // 1300
            Fixed.aaaammdd(h.fechaTraspasoGlobal()),   // referencia: fecha del traspaso original
            LeyendaEstadoCuenta.de(h),
            true);
}

